code.after:
interface Color {
  fill(): string;
}
class Red implements Color { fill() { return "red"; } }
class Blue implements Color { fill() { return "blue"; } }

abstract class Shape {
  constructor(protected color: Color) {}
  abstract draw(): string;
}
class Circle extends Shape {
  draw() { return `circle filled ${this.color.fill()}`; }
}
class Square extends Shape {
  draw() { return `square filled ${this.color.fill()}`; }
}

// Any shape + any color, no new class needed for the combination
new Circle(new Red()).draw();
new Square(new Blue()).draw();
